import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/quesion_imgs_d0b8e93abf304cbfb11a9e6874559909.Db8egEDK.png",e="/bzygq/assets/quesion_imgs_93b4dedaf41a4891872b4fa8b876fb8a.BPwmYzH3.png",s="/bzygq/assets/quesion_imgs_109a24e574fd433494e620e4f1d82328.LdIXQq-m.png",n="/bzygq/assets/quesion_imgs_6ba3d9cc458741e683f47d7ea6a69c07.D94kriYY.png",h="/bzygq/assets/quesion_imgs_bf3e59cd3f844a84a1bc678854b315ea.DP2YQD4y.png",A=JSON.parse('{"title":"什么是命题？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/4.逻辑判断/2.直言命题.md","filePath":"行测/逻辑推理/4.逻辑判断/2.直言命题.md","lastUpdated":1788883925000}'),g={name:"行测/逻辑推理/4.逻辑判断/2.直言命题.md"};function d(p,t,b,c,_,B){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="什么是命题" tabindex="-1">什么是命题？ <a class="header-anchor" href="#什么是命题" aria-label="Permalink to &quot;什么是命题？&quot;">​</a></h1><p>在逻辑判断的范畴中，<strong>命题</strong>是指能够明确判断其真假属性的陈述句 —— 它不包含无法判定对错的疑问句、表达请求的祈使句或抒发情感的感叹句，核心价值在于 “可验证真假”。其中，经过事实或逻辑验证后判断为真的命题，被称为 “真命题”；验证后判断为假的命题，则被称为 “假命题”。</p><ul><li>真命题示例：“猫会爬树”（符合客观事实）、“西瓜是水果”（符合分类逻辑）、“2 是偶数”（符合数学定义）；</li><li>假命题示例：“鱼会飞”（违背客观事实）、“三角形有四条边”（违背几何定义）、“雪是黑色的”（违背常识认知）。</li></ul><p>命题最关键的核心特征的是<strong>明确的真假属性</strong>：任何一句话只要无法判断其对错，就不能称之为命题。例如 “今天天气真好”（主观感叹，无统一真假标准）、“你去哪？”（疑问语气，无真假可言）、“请坐好”（祈使语气，仅表请求），这些都不属于逻辑意义上的命题。</p><h1 id="什么是直言命题" tabindex="-1">什么是直言命题？ <a class="header-anchor" href="#什么是直言命题" aria-label="Permalink to &quot;什么是直言命题？&quot;">​</a></h1><p>直言命题是 <strong>不包含其他命题的简单陈述句</strong>，直接断定 “某类对象是否具有某种性质”，且不能再拆分为更简单的命题。例如：“所有西瓜是水果”“有的学生不是党员”“这个苹果很甜”。</p><p><img src="'+o+'" alt=""></p><p>但是光知道什么是直言命题是不够帮助你解决行测中的考试题目的，我们还需要对直言命题进行一些定义，就拿上面这句话来说。一个完整的直言命题，无论表述形式如何变化，本质上都由 “量项 + 主项 + 联项 + 谓项” 四部分组成，这四部分共同构成了直言命题的 “逻辑骨架”：​</p><ol><li><strong>量项</strong>：专门用来表示判断对象的范围（即 “多少个对象”），是直言命题的 “数量限定词”。根据范围大小，量项可分为三类 —— 全称量项（表示全部对象，如 “所有、全部、凡是”）、特称量项（表示部分对象，如 “有的、部分、有些”）、单称量项（表示单个特定对象，如 “这个、那个、某一个”）；</li><li><strong>主项</strong>：指被判断的核心对象，通常是命题中的名词或名词性短语，是直言命题的 “讨论主体”。比如 “所有学生是努力的” 中，“学生” 就是主项，整个命题围绕 “学生” 展开判断；</li><li><strong>联项</strong>：是连接主项和谓项的 “逻辑桥梁”，专门表示主项是否具有谓项所描述的性质。联项仅分为两类 —— 肯定联项（表示 “具有该性质”，如 “是”）、否定联项（表示 “不具有该性质”，如 “不是”）；</li><li><strong>谓项</strong>：指主项所具有或不具有的具体性质，是对主项的 “特征描述”。比如 “所有学生是努力的” 中，“努力的” 就是谓项，用来描述 “学生” 的特征。</li></ol><p>我们以 “所有西瓜是水果” 为例拆解：量项是 “所有”，主项是 “西瓜”，联项是 “是”（肯定），谓项是 “水果”，完整对应了 “量项 + 主项 + 联项 + 谓项” 的结构。</p><h1 id="命题间关系" tabindex="-1">命题间关系 <a class="header-anchor" href="#命题间关系" aria-label="Permalink to &quot;命题间关系&quot;">​</a></h1><h2 id="命题间关系-1" tabindex="-1">命题间关系 <a class="header-anchor" href="#命题间关系-1" aria-label="Permalink to &quot;命题间关系&quot;">​</a></h2><p>命题间关系，指的是两个或多个命题在<strong>逻辑层面</strong>基于真假值、范围包含等特征形成的关联 —— 核心是通过一个命题的真假，能推导或判定另一个命题的真假，而非命题内容本身的关联（比如 “今天下雨” 和 “明天晴天” 是内容无关，不构成命题间逻辑关系）。</p><p><img src="'+e+'" alt=""></p><ol><li><strong>全同关系</strong>：两个概念的内涵（本质属性）与外延（对象范围）完全一致，仅表述方式不同。例：“北京” 与 “中华人民共和国首都”。</li><li><strong>交叉关系</strong>：两个概念的外延存在部分重合，部分对象同时属于两个概念的范畴。例：“高级工程师” 与 “企业家”（部分人同时具备两种身份）。</li><li><strong>属种关系</strong>：一个概念的外延完全包含于另一个概念的外延之中，其中包含者为 “属概念”，被包含者为 “种概念”。例：“人类”（属概念）包含 “黑人”（种概念）。</li><li><strong>矛盾关系</strong>：两个概念的外延相互排斥，且二者外延之和恰好等于所属属概念的全部外延，无其他可能性。例：“男人” 与 “女人”（在 “性别” 这一属概念下穷尽所有情况）。</li><li><strong>反对关系</strong>：两个概念的外延相互排斥，但二者外延之和小于所属属概念的全部外延，仍存在其他同类对象。例：“数学老师” 与 “英语老师”（属概念 “老师” 中还包含语文老师、物理老师等）。</li></ol><h2 id="命题间真假关系" tabindex="-1">命题间真假关系 <a class="header-anchor" href="#命题间真假关系" aria-label="Permalink to &quot;命题间真假关系&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><ol><li><strong>种属关系（从属关系）</strong>：存在范围大小不同的两个命题，遵循 “大范围真则小范围必真，小范围假则大范围必假” 的推导规则，反之真假无法确定。例：“所有学生都及格了”（大范围）为真→“有的学生及格了”（小范围）必为真；“有的学生及格了”（小范围）为假→“所有学生都及格了”（大范围）必为假。</li><li><strong>矛盾关系</strong>：两个命题无法同时为真，也无法同时为假，必然一真一假，是相互否定的关系。例：“所有鸟都会飞” 与 “有的鸟不会飞”。</li><li><strong>反对关系</strong>：分为上反对和下反对两种，核心体现命题间的 “不能同真” 或 “不能同假” 特性： <ul><li>上反对：两个命题不能同时为真，但可以同时为假，至少有一个为假。例：“所有学生都及格了” 与 “所有学生都没及格”。</li><li>下反对：两个命题不能同时为假，但可以同时为真，至少有一个为真。例：“有的学生及格了” 与 “有的学生没及格”。</li></ul></li></ol><h1 id="直言命题的六大分类" tabindex="-1">直言命题的六大分类 <a class="header-anchor" href="#直言命题的六大分类" aria-label="Permalink to &quot;直言命题的六大分类&quot;">​</a></h1><p><img src="'+n+'" alt=""></p><ol><li><strong>全称命题</strong>（断定一类事物的全部对象） <ul><li>全称肯定：逻辑形式为 “所有 A 是 B”，例如 “所有西瓜都是水果”，断定所有西瓜都具备 “水果” 的属性。</li><li>全称否定：逻辑形式为 “所有 A 不是 B”，例如 “所有人不是狗”，断定所有人都不具备 “狗” 的属性。</li></ul></li><li><strong>特称命题</strong>（断定一类事物中至少一个对象） <ul><li>特称肯定：逻辑形式为 “有的 A 是 B”，例如 “有些人是傻逼”，断定至少有部分人具备 “傻逼” 的属性。</li><li>特称否定：逻辑形式为 “有些 A 不是 B”，例如 “有些人不是傻逼”，断定至少有部分人不具备 “傻逼” 的属性。</li></ul></li><li><strong>单称命题</strong>（断定某一个别对象） <ul><li>单称肯定：逻辑形式为 “a 是 B”，例如 “日本天皇是傻逼”，断定 “日本天皇” 这个个体具备 “傻逼” 的属性。</li><li>单称否定：逻辑形式为 “a 不是 B”，例如 “刘翔不是演员”，断定 “刘翔” 这个个体不具备 “演员” 的属性。</li></ul></li></ol><p>| 【中国电建2019】所有的战争和混乱都是在没有协商、无理可讲的时候发生的；讲理和协商都离不开语言；并非有语言的地方就自动会有说理；有语言的地方必须有自由才能有说理。根据上述信息，下列哪项可以推出？ A. 没有自由就不会发生战争和混乱； B. 所有的战争和混乱都是在可以协商和可以讲理的时候发生的； C. 没有自由就不能讲理，有可能发生战争和混乱； D. 有语言和自由的地方就一定不会发生战争 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：翻译题干：①战争且混乱→¬协商且¬说理；②讲理且协商→语言；③说理→语言且自由。A 项“没有自由→没有战争”无法推出；B 项与①矛盾；C 项“没有自由→¬说理”（否后必否前），可能引发战争，符合；D 项“语言且自由→¬战争”无必然联系</th></tr></thead></table><h1 id="直言命题的当对关系" tabindex="-1">直言命题的当对关系 <a class="header-anchor" href="#直言命题的当对关系" aria-label="Permalink to &quot;直言命题的当对关系&quot;">​</a></h1><h2 id="什么是当对关系" tabindex="-1">什么是当对关系？ <a class="header-anchor" href="#什么是当对关系" aria-label="Permalink to &quot;什么是当对关系？&quot;">​</a></h2><p><img src="'+h+'" alt=""></p><p>直言命题的 “对当关系”，是指<strong>素材相同（即主项 A、谓项 B 完全一致）的不同直言命题之间，存在的固定真假制约关系</strong>。这种关系是行测中 “真假话推理题” 的核心解题工具，能帮助我们快速锁定唯一真 / 假命题的位置，简化推理过程。素材相同的直言命题间，主要存在 4 类关系，每类关系的真假规则如下：​</p><ol><li><strong>矛盾关系</strong>：最核心的对当关系，特征是 “不能同真、不能同假，必然一真一假”（非此即彼，无第三种可能）。</li></ol><p>常见矛盾组合：①所有 A 是 B ↔ 有的 A 不是 B；②所有 A 不是 B ↔ 有的 A 是 B；③这个 A 是 B ↔ 这个 A 不是 B。</p><p>解题价值：题干若明确 “只有一句真话” 或 “只有一句假话”，优先找矛盾关系 —— 真话 / 假话必然在矛盾命题中，其余命题的真假可直接判定。</p><ol start="2"><li><strong>从属关系（又称差等关系）</strong>：体现 “范围大小” 的命题间制约，核心规则是 “真命题不会蕴含假命题”：</li></ol><ul><li>范围大的命题（全称命题：所有 A 是 B / 所有 A 不是 B）为真 → 范围小的命题（特称命题：有的 A 是 B / 有的 A 不是 B）必为真；</li><li>范围小的命题（特称命题）为假 → 范围大的命题（全称命题）必为假；</li><li>反之无法确定：比如 “有的 A 是 B” 为真，不能推出 “所有 A 是 B” 为真（部分真不代表全部真）；“所有 A 是 B” 为假，也不能推出 “有的 A 是 B” 为假。</li></ul><ol start="3"><li><strong>反对关系</strong>：特指 “所有 A 是 B” 与 “所有 A 不是 B” 之间的关系，特征是 “可以同假、不能同真”（即 “至少一假”）。</li></ol><p>规则：①一个命题为真，另一个命题必为假（比如 “所有学生是男生” 为真，“所有学生不是男生” 必为假）；②一个命题为假，另一个命题真假不定（比如 “所有学生是男生” 为假，“所有学生不是男生” 可能真也可能假）。</p><ol start="4"><li><strong>下反对关系</strong>：特指 “有的 A 是 B” 与 “有的 A 不是 B” 之间的关系，特征是 “可以同真、不能同假”（即 “至少一真”）。</li></ol><p>规则：①一个命题为假，另一个命题必为真（比如 “有的学生是男生” 为假，“有的学生不是男生” 必为真）；②一个命题为真，另一个命题真假不定（比如 “有的学生是男生” 为真，“有的学生不是男生” 可能真也可能假）。</p><p>行测逻辑题中，对当关系的核心用途是 “快速破题”：无需逐一代入验证，只需通过关系规则锁定真假命题的范围，再结合题干条件（如 “只有一真”“只有一假”），即可快速推导结论。</p><h2 id="例题" tabindex="-1">例题 <a class="header-anchor" href="#例题" aria-label="Permalink to &quot;例题&quot;">​</a></h2><p>| 【邮储银行2019】4 个队进行比赛，预测如下：（1）冠军不在 ABCD 四个队中产生；（2）冠军在 ABCD 四个队中产生；（3）冠军不在 ABD 中产生；（4）冠军在 A 或 B 中产生。只有一个预测是正确的，冠军是哪个队？ A. A 队； B. B 队； C. C 队； D. D 队 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：（2）（4）为下反对关系命题，必有一真。由只有一个预测正确可知（1）（3）为假，即“冠军将在 ABCD 四个队中产生”且“冠军不在 ABD 中产生”，因此冠军为 C 队</th></tr></thead></table><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><p>| 【中核工业2025】三段论是指以包含三个不同词项的两个直言命题为前提，推出一个直言命题为结论，且每两个直言命题都有一个共同词项的推理。下列属于三段论推理的是？ A. 或者你说错了，或者我听错了，我没有听错表明你说错了； B. 如果寒潮到来，气温就会下降，气温没有下降说明寒潮没有到来； C. 水银是金属，金属是能导电的物体，所以有的能导电的物体是水银； D. 老张是画家，老李是音乐家，他们是朋友，所以画家和音乐家可以做好朋友 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：C 项中“水银是金属”（前提 1）和“金属是能导电的物体”（前提 2）有共同词项“金属”，结论“有的能导电的物体是水银”为直言命题，符合三段论定义。A 项为选言命题，B 项为假言命题，D 项无共同词项，均不符合。</th></tr></thead></table><p>| 【招商银行2020】参加本届“出国交流分享会”的学生都是本科生，本科生都是 4 年制的，有的本科生毕业之后要出国。由此可知？ A. 本届“出国交流分享会”的学生本科毕业后都要出国； B. 只有部分参加本届“出国交流分享会”的学生是本科生； C. 所有参加本届“出国交流分享会”的学生都是 4 年制的； D. 毕业后要出国的都是本科生 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：翻译题干：①参加出国交流会→本科生；②本科生→4 年制；③有的本科生→毕业后出国。连锁推理得“参加出国交流会→4 年制”，即 C 项正确。A 项“有的”不能推出“所有”；B 项与①矛盾；D 项“有的”不能推出“所有”</th></tr></thead></table><p>| 【国家能源2018】所有河南来京打工人员都办理了暂住证；所有办暂住证的人员都获得了就业许可证；有些河南来京的打工人员当上了门卫；有些武术学校的学员当上了门卫；所有的武术学校的学员都未获得就业许可证。如果上述情况是真的，无法确定为真的选项是？ A. 有些门卫没有就业许可证； B. 所有河南来京打工人员都有就业许可证； C. 有些门卫有就业许可证； D. 有些河南来京打工人员是武术学校的学员 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：由题干“所有河南来京打工人员都办理了暂住证；所有办暂住证的人员都获得了就业许可证”可知“所有河南来京打工人员都有就业许可证”（B 项为真）；由“有些河南来京的打工人员当上了门卫”可知“有些门卫有就业许可证”（C 项为真）；由“有些武术学校的学员当上了门卫”和“所有的武术学校的学员都未获得就业许可证”可知“有些门卫没有就业许可证”（A 项为真）；由“所有河南来京打工的都有就业许可证”和“所有的武术学校的学员都未获得就业许可证”可知“所有河南来京打工人员都不是武术学校的学员”，因此 D 项为假。</th></tr></thead></table>',47)])])}const m=a(g,[["render",d]]);export{A as __pageData,m as default};
